import{_ as t,o as i,c as a,ah as r}from"./chunks/framework.D4KxWb5R.js";const m=JSON.parse('{"title":"Supervision des indicateurs","description":"","frontmatter":{},"headers":[],"relativePath":"guide/administration/indicators.md","filePath":"src/guide/administration/indicators.md"}'),n={name:"guide/administration/indicators.md"};function s(o,e,d,u,l,c){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="supervision-des-indicateurs" tabindex="-1">Supervision des indicateurs <a class="header-anchor" href="#supervision-des-indicateurs" aria-label="Permalink to &quot;Supervision des indicateurs&quot;">​</a></h1><p><strong>Administration → Supervision</strong> montre les indicateurs consolidés remontés par chaque produit. Ouvert au PDG, au Pôle Exploitation et au volet Finance.</p><p>M&#39;City IQ n&#39;héberge que des <strong>valeurs agrégées</strong>, jamais le détail opérationnel d&#39;un produit : celui-ci se consulte dans le back-office du produit.</p><h2 id="lire-la-supervision" tabindex="-1">Lire la supervision <a class="header-anchor" href="#lire-la-supervision" aria-label="Permalink to &quot;Lire la supervision&quot;">​</a></h2><p>Pour chaque indicateur actif, la page affiche :</p><ul><li>sa fenêtre (par exemple « fenêtre de 30 jours ») ;</li><li>pour chaque produit source, la <strong>dernière valeur</strong> remontée, sa date et, le cas échéant, sa <strong>répartition</strong> (par domaine d&#39;activité, par exemple) ;</li><li>un <strong>total</strong>, uniquement pour les indicateurs additifs (somme). Des utilisateurs distincts ou des ratios ne s&#39;additionnent pas d&#39;un produit à l&#39;autre.</li></ul><p>« Pas encore remonté » signale un produit source qui n&#39;a encore rien envoyé.</p><h2 id="les-indicateurs-de-depart" tabindex="-1">Les indicateurs de départ <a class="header-anchor" href="#les-indicateurs-de-depart" aria-label="Permalink to &quot;Les indicateurs de départ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Indicateur</th><th>Agrégation</th></tr></thead><tbody><tr><td>Utilisateurs actifs (<code>active_users</code>)</td><td>Décompte distinct</td></tr><tr><td>Prestataires et vendeurs actifs (<code>active_providers</code>)</td><td>Décompte distinct</td></tr><tr><td>Alertes publiées (<code>published_alerts</code>)</td><td>Somme</td></tr><tr><td>Répartition de l&#39;activité par domaine (<code>activity_by_domain</code>)</td><td>Somme, avec répartition</td></tr></tbody></table><p>Le PDG choisit quels produits remontent chaque indicateur, et en ajoute de nouveaux, dans <a href="./settings.html#definitions-d-indicateurs">Définitions d&#39;indicateurs</a>.</p><h2 id="quand-les-valeurs-ne-remontent-plus" tabindex="-1">Quand les valeurs ne remontent plus <a class="header-anchor" href="#quand-les-valeurs-ne-remontent-plus" aria-label="Permalink to &quot;Quand les valeurs ne remontent plus&quot;">​</a></h2><p>En mode relevé, si la collecte échoue trois fois de suite, le PDG et les équipes du produit sont prévenus. Le <a href="./logs.html">journal de synchronisation</a> montre chaque relevé et son erreur ; le PDG peut relancer une collecte avec <strong>Relever maintenant</strong> sur la page <strong>Intégration API</strong> du produit.</p>',12)])])}const h=t(n,[["render",s]]);export{m as __pageData,h as default};
